import fs from'node:fs';import vm from'node:vm';import assert from'node:assert/strict';
const root=new URL('../',import.meta.url),dir=new URL('content/research/2026-11-11-geschichte-bundestagswahlen/',root),input=JSON.parse(fs.readFileSync(new URL('input.json',dir))),pack=JSON.parse(fs.readFileSync(new URL('draft-pack.json',dir))),daily=JSON.parse(fs.readFileSync(new URL('daily-catalogue-check.json',dir))),parallel=JSON.parse(fs.readFileSync(new URL('parallel-pr-check.json',dir))),c={window:{}};vm.createContext(c);vm.runInContext(fs.readFileSync(new URL('content/approved.js',root),'utf8'),c);
const games=['moreless','estimate','facts','jeopardy'];assert.deepEqual(games.map(g=>pack[g].length),[2,4,6,8]);assert.equal(new Set(input.questions.map(q=>q.semantic_key)).size,20);assert.equal(new Set(input.questions.flatMap(q=>q.observation_keys)).size,22);
for(const l of['easy','medium','hard'])assert.deepEqual(pack.facts.filter(q=>q.difficulty===l).map(q=>q.a).sort(),[false,true]);
for(const q of pack.moreless){assert.notEqual(q.lv,q.rv);assert(q.notes.includes('Gleiche'));assert(!pack.moreless.some(x=>x!==q&&x.l===q.r&&x.r===q.l&&x.metric===q.metric));}
const norm=v=>String(v??'').toLocaleLowerCase('de').normalize('NFKD').replace(/\p{M}/gu,'').replace(/[^a-z0-9]+/g,' ').trim(),main=games.flatMap(g=>c.window.GAME_CONTENT_PACK[g]).map(q=>norm(JSON.stringify(q))).join('\n');for(const q of input.questions){assert(!main.includes(norm(q.semantic_key)));assert(q.source_refs.length&&q.rounding&&q.notes);}
assert.equal(daily.database_writes,0);assert.equal(daily.catalogue_total,7187);assert.equal(daily.target_observation_matches,0);assert.equal(daily.target_observations_checked,22);assert.equal(parallel.open_pr_count,41);
for(const kind of['card','detail']){const svg=fs.readFileSync(new URL(`visuals/geschichte-bundestagswahl-neutral-${kind}.svg`,dir),'utf8');assert(svg.includes(kind==='card'?'width="720" height="540"':'width="960" height="540"'));assert(svg.includes('x="40" y="40"'));assert(!/<text\b|SPD|CDU|FDP|CSU|NPD|GRÜNE|19[0-9]{2}|[0-9]+[,.][0-9]+\s*%/.test(svg));}
assert(pack.jeopardy.every(q=>q.visual===null));console.log('Bundestagswahl history draft checks passed');
